<script lang="ts">
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { API, Constants } from "$lib";
	import ErrorComponent from "$lib/components/ErrorComponent.svelte";
	import MangaSearchEntryCard from "$lib/components/MangaSearchEntryCard.svelte";
	import * as Empty from "$lib/components/ui/empty";
	import Grid from "$lib/components/ui/Grid.svelte";
	import { Spinner } from "$lib/components/ui/spinner";
	import { Button } from "$lib/components/ui/button";
	import ViewModeToggles from "$lib/components/ViewModeToggles.svelte";
	import { getManga } from "$lib/Context";
	import { mangaView } from "$lib/stores";
	import { HTTPError } from "$lib/HTTP";
	import { createSafeReadOwner } from "$platform/safe-read-owner";
	import { onMount } from "svelte";
	const manga = $derived(getManga()());
	let feed = $state<MangaFeedResponse>(), isMounted = $state(false), isLoading = $state(false), mountedLifecycle = $state(false);
	let isGrid = $derived($mangaView === "grid"), error = $state<Constants.Error.Error>();
	const reads = createSafeReadOwner();
	let observed = "", pending = false, draining = false;
	const contextKey = () => JSON.stringify([manga.id, page.url.href]);
	function queueRecommendations() {
		if (!reads.isLive()) return;
		reads.invalidate(); pending = true; feed = undefined; error = undefined; isMounted = false;
		void Promise.resolve().then(drain);
	}
	async function drain() {
		if (draining || !reads.isLive()) return;
		draining = true; isLoading = true;
		try {
			while (pending && reads.isLive()) {
				pending = false;
				const id = manga.id, key = contextKey(), intent = reads.capture(() => contextKey() === key);
				try {
					// A fresh read rechecks public availability, including cached-empty
					// history states; old history DTOs never replace the current reply.
					const res = await API.Manga.Recommendations(id);
					if (!intent.alive()) { if (intent.current()) error = new Constants.Error.Error("Recommendations unavailable", "Navigation interrupted this read. Retry the current title."); continue; }
					if (res?.status !== 200 || !res.body || !Array.isArray(res.body.data)) throw new HTTPError(res?.status ?? 0, `Recommendations could not be loaded${res?.status ? ` (HTTP ${res.status})` : " because the connection ended"}. No empty result was inferred. Retry when the current title is available.`);
					feed = res.body;
					replaceState(page.url.href, { ...page.state, _$Recommendations_feed: $state.snapshot(feed), _$Recommendations_context: key });
				} catch (cause) {
					if (intent.current()) error = new Constants.Error.Error("Recommendations unavailable", cause instanceof HTTPError ? cause.body : "Recommendations could not be loaded. Retry the current title when the service is available.");
				} finally { if (intent.current()) isMounted = true; }
			}
		} finally { draining = false; if (reads.isLive()) isLoading = false; }
	}
	onMount(() => { mountedLifecycle = true; });
	$effect.pre(() => {
		if (!mountedLifecycle || !reads.isLive()) return;
		const key = contextKey(); if (key === observed) return;
		observed = key; queueRecommendations();
	});
</script>

{#if error}
	<ErrorComponent {error} />
	<Button variant="outline" disabled={isLoading} onclick={queueRecommendations}>Retry recommendations</Button>
{:else if isMounted && feed?.data?.length}
	<section class="space-y-2">
		<header class="flex items-center gap-2">
			<ViewModeToggles />
		</header>
		<Grid class="gap-3" breakpoints={isGrid ? Constants.MangaPageGridBreakpoints : { 0: 2, 768: 1 }}>
			{#each feed.data as manga (manga)}
				<article>
					<MangaSearchEntryCard {manga} {isGrid} />
				</article>
			{/each}
		</Grid>
	</section>
{:else if isMounted}
	<Empty.Root>
		<Empty.Title>No recommendations found</Empty.Title>
	</Empty.Root>
{:else}
	<Empty.Root>
		<Spinner class="size-10" />
	</Empty.Root>
{/if}
